"""Asyncio Unix-socket server that owns the vehicle link and answers RPCs."""

from __future__ import annotations

import asyncio
import contextlib
import signal
from typing import TYPE_CHECKING

from mavctl.adapter.base import VehicleAdapter
from mavctl.daemon import wire
from mavctl.models import DaemonResponse, ExitCode, RpcRequest
from mavctl.paths import runtime_dir, socket_path

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable

# Max bytes accepted for a single request frame (defensive bound).
_MAX_FRAME = 64 * 1024


class DaemonServer:
    """Serves RPC requests over a Unix socket, backed by a vehicle adapter.

    The adapter maintains the live MAVLink snapshot on its own reader thread;
    the server's request handlers only perform cheap snapshot reads, so no
    handler blocks the event loop.
    """

    def __init__(self, adapter: VehicleAdapter, connection_string: str) -> None:
        self._adapter = adapter
        self._connection_string = connection_string
        self._stop_event = asyncio.Event()
        self._server: asyncio.AbstractServer | None = None
        self._methods: dict[str, Callable[[RpcRequest], DaemonResponse]] = {
            "ping": self._m_ping,
            "status": self._m_status,
            "telemetry": self._m_telemetry,
            "shutdown": self._m_shutdown,
        }

    async def serve(self) -> None:
        """Open the link, bind the socket, and serve until asked to stop."""

        self._adapter.connect()
        runtime_dir().mkdir(parents=True, exist_ok=True)
        sock = socket_path()
        with contextlib.suppress(FileNotFoundError):
            sock.unlink()

        self._install_signal_handlers()
        self._server = await asyncio.start_unix_server(self._handle_client, path=str(sock))
        try:
            await self._stop_event.wait()
        finally:
            await self._shutdown()

    def request_stop(self) -> None:
        """Signal the serve loop to unwind (safe to call from a signal handler)."""

        self._stop_event.set()

    # -- connection handling ----------------------------------------------

    async def _handle_client(
        self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter
    ) -> None:
        try:
            line = await reader.readline()
            if not line or len(line) > _MAX_FRAME:
                return
            response = self._dispatch(line)
            writer.write(wire.encode(response.model_dump()))
            await writer.drain()
        except (ConnectionError, asyncio.IncompleteReadError):
            return
        finally:
            writer.close()
            with contextlib.suppress(ConnectionError, asyncio.CancelledError):
                await writer.wait_closed()

    def _dispatch(self, line: bytes) -> DaemonResponse:
        try:
            request = RpcRequest.model_validate(wire.decode(line))
        except (ValueError, TypeError) as exc:
            return DaemonResponse.failure(ExitCode.USAGE_ERROR, f"malformed request: {exc}")

        handler = self._methods.get(request.method)
        if handler is None:
            return DaemonResponse.failure(
                ExitCode.GENERAL_ERROR, f"unknown method: {request.method!r}"
            )
        try:
            return handler(request)
        except Exception as exc:  # noqa: BLE001 - never let a handler crash the daemon
            return DaemonResponse.failure(ExitCode.GENERAL_ERROR, f"internal error: {exc}")

    # -- RPC methods -------------------------------------------------------

    def _m_ping(self, _request: RpcRequest) -> DaemonResponse:
        return DaemonResponse.success(
            {"pong": True, "connection_string": self._connection_string}
        )

    def _m_status(self, _request: RpcRequest) -> DaemonResponse:
        return DaemonResponse.success(self._adapter.get_state().model_dump())

    def _m_telemetry(self, _request: RpcRequest) -> DaemonResponse:
        state = self._adapter.get_state()
        if not state.connected:
            return DaemonResponse.failure(
                ExitCode.VEHICLE_NOT_CONNECTED,
                "vehicle not connected (no recent heartbeat)",
                {"connection_string": self._connection_string},
            )
        return DaemonResponse.success(self._adapter.get_telemetry().model_dump())

    def _m_shutdown(self, _request: RpcRequest) -> DaemonResponse:
        self.request_stop()
        return DaemonResponse.success({"stopping": True})

    # -- teardown ----------------------------------------------------------

    def _install_signal_handlers(self) -> None:
        loop = asyncio.get_running_loop()
        for sig in (signal.SIGTERM, signal.SIGINT):
            with contextlib.suppress(NotImplementedError):
                loop.add_signal_handler(sig, self.request_stop)

    async def _shutdown(self) -> None:
        if self._server is not None:
            self._server.close()
            with contextlib.suppress(Exception):
                await self._server.wait_closed()
            self._server = None
        self._adapter.disconnect()
        with contextlib.suppress(FileNotFoundError):
            socket_path().unlink()


def _serve_target(target: Callable[[], Awaitable[None]]) -> None:  # pragma: no cover
    asyncio.run(target())

"""Synchronous Unix-socket client used by the CLI to talk to the daemon."""

from __future__ import annotations

import socket
from typing import Any

from mavctl.daemon import wire
from mavctl.models import DaemonResponse
from mavctl.paths import socket_path


class DaemonNotRunningError(Exception):
    """Raised when no daemon is listening on the expected socket."""


def _read_frame(sock: socket.socket) -> bytes:
    chunks: list[bytes] = []
    while True:
        chunk = sock.recv(4096)
        if not chunk:
            break
        chunks.append(chunk)
        if b"\n" in chunk:
            break
    return b"".join(chunks)


def call_daemon(
    method: str,
    params: dict[str, Any] | None = None,
    timeout: float = 5.0,
) -> DaemonResponse:
    """Send one RPC request to the daemon and return its response.

    Raises:
        DaemonNotRunningError: if the socket is absent or refuses the connection.
    """

    path = socket_path()
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    try:
        try:
            sock.connect(str(path))
        except (FileNotFoundError, ConnectionRefusedError) as exc:
            raise DaemonNotRunningError(str(exc)) from exc
        sock.sendall(wire.encode({"method": method, "params": params or {}}))
        line = _read_frame(sock)
    finally:
        sock.close()

    if not line:
        raise DaemonNotRunningError("daemon closed the connection without responding")
    return DaemonResponse.model_validate(wire.decode(line))


def is_daemon_running() -> bool:
    """Return True if a daemon answers a ping on the socket."""

    try:
        return call_daemon("ping", timeout=1.0).ok
    except DaemonNotRunningError:
        return False
    except (OSError, ValueError):
        return False


class DaemonClient:
    """Thin object wrapper around :func:`call_daemon` for callers that
    prefer a handle (e.g. tests injecting a fake)."""

    def __init__(self, timeout: float = 5.0) -> None:
        self._timeout = timeout

    def call(self, method: str, params: dict[str, Any] | None = None) -> DaemonResponse:
        return call_daemon(method, params, timeout=self._timeout)

    def is_running(self) -> bool:
        return is_daemon_running()

"""Daemon process lifecycle: pidfile management, spawning, and stopping."""

from __future__ import annotations

import os
import signal
import subprocess
import sys
import time

from mavctl.daemon.client import is_daemon_running
from mavctl.paths import log_path, pid_path, runtime_dir, socket_path


def read_pid() -> int | None:
    """Return the pid recorded in the pidfile, or None if absent/unreadable."""

    path = pid_path()
    try:
        text = path.read_text().strip()
    except FileNotFoundError:
        return None
    try:
        return int(text)
    except ValueError:
        return None


def write_pid(pid: int) -> None:
    """Record ``pid`` in the pidfile, creating the runtime dir if needed."""

    runtime_dir().mkdir(parents=True, exist_ok=True)
    pid_path().write_text(f"{pid}\n")


def clear_pid() -> None:
    """Remove the pidfile if present."""

    try:
        pid_path().unlink()
    except FileNotFoundError:
        pass


def pid_alive(pid: int) -> bool:
    """Return True if a process with ``pid`` exists and is signalable."""

    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def is_running() -> bool:
    """Return True if a live daemon is recorded and reachable.

    Cleans up a stale pidfile whose process is gone.
    """

    pid = read_pid()
    if pid is None:
        return False
    if not pid_alive(pid):
        clear_pid()
        return False
    return True


def spawn(connection_string: str, heartbeat_timeout: float, startup_timeout: float = 12.0) -> int:
    """Launch a detached daemon process and wait until it answers a ping.

    Returns:
        The pid of the started daemon.

    Raises:
        RuntimeError: if the daemon exits early or never becomes ready.
    """

    runtime_dir().mkdir(parents=True, exist_ok=True)
    log = log_path().open("a")
    try:
        proc = subprocess.Popen(
            [
                sys.executable,
                "-m",
                "mavctl.daemon",
                "--connect",
                connection_string,
                "--heartbeat-timeout",
                str(heartbeat_timeout),
            ],
            stdin=subprocess.DEVNULL,
            stdout=log,
            stderr=log,
            start_new_session=True,
            env=os.environ.copy(),
        )
    finally:
        log.close()

    deadline = time.monotonic() + startup_timeout
    while time.monotonic() < deadline:
        exit_code = proc.poll()
        if exit_code is not None:
            raise RuntimeError(
                f"daemon exited during startup (code {exit_code}); see {log_path()}"
            )
        if is_daemon_running():
            return proc.pid
        time.sleep(0.15)

    proc.terminate()
    raise RuntimeError(f"daemon did not become ready within {startup_timeout:.0f}s")


def stop(term_timeout: float = 8.0) -> bool:
    """Stop the running daemon via SIGTERM, escalating to SIGKILL.

    Returns:
        True if a daemon was stopped, False if none was running.
    """

    pid = read_pid()
    if pid is None or not pid_alive(pid):
        clear_pid()
        _cleanup_socket()
        return False

    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        clear_pid()
        _cleanup_socket()
        return False

    deadline = time.monotonic() + term_timeout
    while time.monotonic() < deadline:
        if not pid_alive(pid):
            break
        time.sleep(0.1)
    else:
        with _suppress_lookup():
            os.kill(pid, signal.SIGKILL)

    clear_pid()
    _cleanup_socket()
    return True


def _cleanup_socket() -> None:
    try:
        socket_path().unlink()
    except FileNotFoundError:
        pass


class _suppress_lookup:
    def __enter__(self) -> None:
        return None

    def __exit__(self, exc_type: object, exc: object, tb: object) -> bool:
        return exc_type is not None and issubclass(exc_type, ProcessLookupError)

