"""Safety-guard framework for state-changing (dangerous) commands.

Each guard is a pure function of the cached :class:`VehicleState` plus command
parameters, returning a :class:`GuardDecision`. The daemon runs the relevant
guard before touching the adapter; ``--dry-run`` runs the guard and reports
without executing. Rejections carry a machine-readable ``reason``, a human
``message``, and a ``hint`` telling an agent what to do next.
"""

from __future__ import annotations

from pydantic import BaseModel

from mavctl.models import ExitCode, VehicleState

# Defaults for precondition thresholds.
DEFAULT_MAX_TAKEOFF_ALT_M = 120.0
DEFAULT_MIN_GPS_FIX_TYPE = 3  # 3D fix
_GUIDED = "GUIDED"


class GuardConfig(BaseModel):
    """Tunable guard thresholds."""

    max_takeoff_alt_m: float = DEFAULT_MAX_TAKEOFF_ALT_M
    min_gps_fix_type: int = DEFAULT_MIN_GPS_FIX_TYPE


class GuardCheck(BaseModel):
    """One named precondition check and its result."""

    name: str
    passed: bool
    detail: str


class GuardDecision(BaseModel):
    """Outcome of running a command's guards.

    ``allowed`` says whether execution may proceed. When rejected,
    ``reason``/``message``/``hint`` explain why and what to do, and
    ``exit_code`` is the process code to surface. ``already_satisfied`` marks
    the idempotent case: allowed, but the desired state already holds.
    """

    allowed: bool
    action: str
    checks: list[GuardCheck] = []
    reason: str | None = None
    message: str | None = None
    hint: str | None = None
    exit_code: ExitCode = ExitCode.SUCCESS
    already_satisfied: bool = False
    note: str | None = None


def _passed(name: str, detail: str) -> GuardCheck:
    return GuardCheck(name=name, passed=True, detail=detail)


def _reject(
    action: str,
    reason: str,
    message: str,
    hint: str,
    checks: list[GuardCheck],
    failed_check: GuardCheck,
    exit_code: ExitCode = ExitCode.SAFETY_REJECTED,
) -> GuardDecision:
    return GuardDecision(
        allowed=False,
        action=action,
        checks=[*checks, failed_check],
        reason=reason,
        message=message,
        hint=hint,
        exit_code=exit_code,
    )


def _confirm_check(action: str, confirm: bool) -> GuardDecision | None:
    """Shared first gate: every dangerous command requires ``--confirm``."""

    if confirm:
        return None
    return _reject(
        action=action,
        reason="confirmation_required",
        message=f"{action} is a state-changing command and requires explicit confirmation",
        hint=f"re-run with --confirm (and --dry-run first to preview): mavctl {action} --confirm",
        checks=[],
        failed_check=GuardCheck(name="confirm", passed=False, detail="--confirm not provided"),
    )


def check_arm(state: VehicleState, *, confirm: bool, config: GuardConfig) -> GuardDecision:
    action = "arm"
    gate = _confirm_check(action, confirm)
    if gate is not None:
        return gate
    checks = [_passed("confirm", "confirmed")]

    if state.armed:
        return GuardDecision(
            allowed=True,
            action=action,
            checks=[*checks, _passed("already_armed", "vehicle already armed")],
            already_satisfied=True,
            note="already armed",
        )

    fix = state.gps.fix_type or 0
    if fix < config.min_gps_fix_type:
        return _reject(
            action=action,
            reason="gps_not_ready",
            message=f"GPS fix insufficient for arming (fix_type={fix}, need >= {config.min_gps_fix_type})",
            hint="wait for a 3D GPS fix before arming (check: mavctl status)",
            checks=checks,
            failed_check=GuardCheck(
                name="gps_fix", passed=False, detail=f"fix_type={fix} ({state.gps.fix_label})"
            ),
        )
    checks.append(_passed("gps_fix", f"fix_type={fix} ({state.gps.fix_label})"))
    return GuardDecision(allowed=True, action=action, checks=checks)


def check_disarm(
    state: VehicleState, *, confirm: bool, force: bool, config: GuardConfig
) -> GuardDecision:
    action = "disarm"
    gate = _confirm_check(action, confirm)
    if gate is not None:
        return gate
    checks = [_passed("confirm", "confirmed")]

    if state.armed is False:
        return GuardDecision(
            allowed=True,
            action=action,
            checks=[*checks, _passed("already_disarmed", "vehicle already disarmed")],
            already_satisfied=True,
            note="already disarmed",
        )

    airborne = state.landed_state == "in_air" or (
        state.relative_alt_m is not None and state.relative_alt_m > 1.0
    )
    if airborne and not force:
        return _reject(
            action=action,
            reason="in_flight",
            message="refusing to disarm: vehicle appears to be airborne",
            hint="land first (mavctl land --confirm) or override with --force (DANGEROUS)",
            checks=checks,
            failed_check=GuardCheck(
                name="on_ground",
                passed=False,
                detail=f"landed_state={state.landed_state} rel_alt={state.relative_alt_m}",
            ),
        )
    checks.append(
        _passed("on_ground", "forced" if force else f"landed_state={state.landed_state}")
    )
    return GuardDecision(allowed=True, action=action, checks=checks)


def check_mode(
    state: VehicleState, mode: str, available: list[str], *, confirm: bool
) -> GuardDecision:
    action = "mode"
    gate = _confirm_check(action, confirm)
    if gate is not None:
        return gate
    checks = [_passed("confirm", "confirmed")]
    target = mode.upper()

    if available and target not in available:
        return _reject(
            action=action,
            reason="unknown_mode",
            message=f"unknown flight mode {target!r}",
            hint=f"choose one of: {', '.join(available)}",
            checks=checks,
            failed_check=GuardCheck(name="mode_known", passed=False, detail=f"{target} not available"),
            exit_code=ExitCode.USAGE_ERROR,
        )
    checks.append(_passed("mode_known", f"{target} is available"))

    if state.flight_mode == target:
        return GuardDecision(
            allowed=True,
            action=action,
            checks=[*checks, _passed("already_in_mode", f"already in {target}")],
            already_satisfied=True,
            note=f"already in {target}",
        )
    return GuardDecision(allowed=True, action=action, checks=checks)


def check_takeoff(
    state: VehicleState, altitude_m: float, *, confirm: bool, config: GuardConfig
) -> GuardDecision:
    action = "takeoff"
    gate = _confirm_check(action, confirm)
    if gate is not None:
        return gate
    checks = [_passed("confirm", "confirmed")]

    if altitude_m <= 0:
        return _reject(
            action=action,
            reason="invalid_altitude",
            message=f"takeoff altitude must be positive (got {altitude_m})",
            hint="provide a positive --alt in metres",
            checks=checks,
            failed_check=GuardCheck(name="alt_positive", passed=False, detail=f"alt={altitude_m}"),
            exit_code=ExitCode.USAGE_ERROR,
        )
    checks.append(_passed("alt_positive", f"alt={altitude_m}m"))

    if altitude_m > config.max_takeoff_alt_m:
        return _reject(
            action=action,
            reason="altitude_limit",
            message=f"requested altitude {altitude_m}m exceeds limit {config.max_takeoff_alt_m}m",
            hint=f"request <= {config.max_takeoff_alt_m}m, or raise the configured limit",
            checks=checks,
            failed_check=GuardCheck(
                name="alt_limit", passed=False, detail=f"{altitude_m} > {config.max_takeoff_alt_m}"
            ),
        )
    checks.append(_passed("alt_limit", f"{altitude_m} <= {config.max_takeoff_alt_m}"))

    if state.flight_mode != _GUIDED:
        return _reject(
            action=action,
            reason="wrong_mode",
            message=f"takeoff requires {_GUIDED} mode (current: {state.flight_mode})",
            hint=f"set mode then arm then takeoff: mavctl mode {_GUIDED} --confirm && "
            "mavctl arm --confirm && mavctl takeoff --alt <m> --confirm",
            checks=checks,
            failed_check=GuardCheck(
                name="mode_guided", passed=False, detail=f"mode={state.flight_mode}"
            ),
        )
    checks.append(_passed("mode_guided", f"mode={state.flight_mode}"))

    if not state.armed:
        return _reject(
            action=action,
            reason="not_armed",
            message="takeoff requires the vehicle to be armed",
            hint="arm first: mavctl arm --confirm (then mavctl takeoff --alt <m> --confirm)",
            checks=checks,
            failed_check=GuardCheck(name="armed", passed=False, detail=f"armed={state.armed}"),
        )
    checks.append(_passed("armed", "armed"))
    return GuardDecision(allowed=True, action=action, checks=checks)


def check_land(state: VehicleState, *, confirm: bool) -> GuardDecision:
    action = "land"
    gate = _confirm_check(action, confirm)
    if gate is not None:
        return gate
    checks = [_passed("confirm", "confirmed")]

    if state.armed is False or state.landed_state == "on_ground":
        return GuardDecision(
            allowed=True,
            action=action,
            checks=[*checks, _passed("already_landed", "already on ground / disarmed")],
            already_satisfied=True,
            note="already on ground",
        )
    return GuardDecision(allowed=True, action=action, checks=checks)


def check_rtl(state: VehicleState, *, confirm: bool) -> GuardDecision:
    action = "rtl"
    gate = _confirm_check(action, confirm)
    if gate is not None:
        return gate
    checks = [_passed("confirm", "confirmed")]

    if state.armed is False or state.landed_state == "on_ground":
        return GuardDecision(
            allowed=True,
            action=action,
            checks=[*checks, _passed("already_home", "already on ground / disarmed")],
            already_satisfied=True,
            note="already on ground",
        )
    return GuardDecision(allowed=True, action=action, checks=checks)

"""Asyncio Unix-socket server that owns the vehicle link and answers RPCs."""

from __future__ import annotations

import asyncio
import contextlib
import signal
from collections.abc import Awaitable, Callable
from typing import Any

from mavctl.adapter.base import AdapterError, VehicleAdapter
from mavctl.daemon import guards, wire
from mavctl.daemon.guards import GuardConfig, GuardDecision
from mavctl.models import CommandOutcome, DaemonResponse, ExitCode, RpcRequest
from mavctl.paths import runtime_dir, socket_path

# Max bytes accepted for a single request frame (defensive bound).
_MAX_FRAME = 64 * 1024

# Default --wait timeout in seconds when the client does not specify one.
_DEFAULT_WAIT_TIMEOUT = 60.0

# Fraction of target altitude that counts as "takeoff reached".
_TAKEOFF_REACHED_FRACTION = 0.95

Handler = Callable[[RpcRequest], Awaitable[DaemonResponse]]


class DaemonServer:
    """Serves RPC requests over a Unix socket, backed by a vehicle adapter.

    The adapter maintains the live MAVLink snapshot on its own reader thread;
    fast handlers (ping/status/telemetry) only read that snapshot, while
    command handlers run the blocking adapter verbs in an executor so the
    event loop stays responsive.
    """

    def __init__(
        self,
        adapter: VehicleAdapter,
        connection_string: str,
        guard_config: GuardConfig | None = None,
    ) -> None:
        self._adapter = adapter
        self._connection_string = connection_string
        self._guard_config = guard_config or GuardConfig()
        self._stop_event = asyncio.Event()
        self._server: asyncio.AbstractServer | None = None
        self._methods: dict[str, Handler] = {
            "ping": self._m_ping,
            "status": self._m_status,
            "telemetry": self._m_telemetry,
            "shutdown": self._m_shutdown,
            "arm": self._m_arm,
            "disarm": self._m_disarm,
            "mode": self._m_mode,
            "takeoff": self._m_takeoff,
            "land": self._m_land,
            "rtl": self._m_rtl,
        }

    async def serve(self) -> None:
        """Open the link, bind the socket, and serve until asked to stop."""

        self._adapter.connect()
        runtime_dir().mkdir(parents=True, exist_ok=True)
        sock = socket_path()
        with contextlib.suppress(FileNotFoundError):
            sock.unlink()

        self._install_signal_handlers()
        self._server = await asyncio.start_unix_server(self._handle_client, path=str(sock))
        try:
            await self._stop_event.wait()
        finally:
            await self._shutdown()

    def request_stop(self) -> None:
        """Signal the serve loop to unwind (safe to call from a signal handler)."""

        self._stop_event.set()

    # -- connection handling ----------------------------------------------

    async def _handle_client(
        self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter
    ) -> None:
        try:
            line = await reader.readline()
            if not line or len(line) > _MAX_FRAME:
                return
            response = await self._dispatch(line)
            writer.write(wire.encode(response.model_dump()))
            await writer.drain()
        except (ConnectionError, asyncio.IncompleteReadError):
            return
        finally:
            writer.close()
            with contextlib.suppress(ConnectionError, asyncio.CancelledError):
                await writer.wait_closed()

    async def _dispatch(self, line: bytes) -> DaemonResponse:
        try:
            request = RpcRequest.model_validate(wire.decode(line))
        except (ValueError, TypeError) as exc:
            return DaemonResponse.failure(ExitCode.USAGE_ERROR, f"malformed request: {exc}")

        handler = self._methods.get(request.method)
        if handler is None:
            return DaemonResponse.failure(
                ExitCode.GENERAL_ERROR, f"unknown method: {request.method!r}"
            )
        try:
            return await handler(request)
        except Exception as exc:  # noqa: BLE001 - never let a handler crash the daemon
            return DaemonResponse.failure(ExitCode.GENERAL_ERROR, f"internal error: {exc}")

    # -- fast RPC methods --------------------------------------------------

    async def _m_ping(self, _request: RpcRequest) -> DaemonResponse:
        return DaemonResponse.success(
            {"pong": True, "connection_string": self._connection_string}
        )

    async def _m_status(self, _request: RpcRequest) -> DaemonResponse:
        return DaemonResponse.success(self._adapter.get_state().model_dump())

    async def _m_telemetry(self, _request: RpcRequest) -> DaemonResponse:
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        return DaemonResponse.success(self._adapter.get_telemetry().model_dump())

    async def _m_shutdown(self, _request: RpcRequest) -> DaemonResponse:
        self.request_stop()
        return DaemonResponse.success({"stopping": True})

    # -- command RPC methods ----------------------------------------------

    async def _m_arm(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        decision = guards.check_arm(state, confirm=_flag(p, "confirm"), config=self._guard_config)
        pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
        if pre is not None:
            return pre
        outcome = await self._blocking(self._adapter.arm, _flag(p, "force"))
        return self._command_result("arm", outcome)

    async def _m_disarm(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        decision = guards.check_disarm(
            state, confirm=_flag(p, "confirm"), force=_flag(p, "force"), config=self._guard_config
        )
        pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
        if pre is not None:
            return pre
        outcome = await self._blocking(self._adapter.disarm, _flag(p, "force"))
        return self._command_result("disarm", outcome)

    async def _m_mode(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        mode = str(p.get("mode", "")).upper()
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        decision = guards.check_mode(
            state, mode, self._adapter.mode_names(), confirm=_flag(p, "confirm")
        )
        pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
        if pre is not None:
            return pre
        outcome = await self._blocking(self._adapter.set_mode, mode)
        if not outcome.accepted:
            return self._command_result("mode", outcome)
        waited = await self._maybe_wait(
            p, lambda: self._adapter.get_state().flight_mode == mode
        )
        if waited is False:
            return self._wait_timeout("mode", outcome, p, f"mode did not switch to {mode}")
        return self._command_result("mode", outcome, waited=waited)

    async def _m_takeoff(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        try:
            alt = float(p.get("alt"))
        except (TypeError, ValueError):
            return DaemonResponse.failure(ExitCode.USAGE_ERROR, "takeoff requires numeric --alt")
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        decision = guards.check_takeoff(
            state, alt, confirm=_flag(p, "confirm"), config=self._guard_config
        )
        pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
        if pre is not None:
            return pre
        outcome = await self._blocking(self._adapter.takeoff, alt)
        if not outcome.accepted:
            return self._command_result("takeoff", outcome)
        target = alt * _TAKEOFF_REACHED_FRACTION
        waited = await self._maybe_wait(p, lambda: self._reached_altitude(target))
        if waited is False:
            return self._wait_timeout(
                "takeoff", outcome, p, f"altitude {target:.1f}m not reached"
            )
        return self._command_result("takeoff", outcome, waited=waited)

    async def _m_land(self, request: RpcRequest) -> DaemonResponse:
        return await self._m_descent(request, "land", self._adapter.land)

    async def _m_rtl(self, request: RpcRequest) -> DaemonResponse:
        return await self._m_descent(request, "rtl", self._adapter.rtl)

    async def _m_descent(
        self, request: RpcRequest, action: str, verb: Callable[[], CommandOutcome]
    ) -> DaemonResponse:
        p = request.params
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        decision = (
            guards.check_land(state, confirm=_flag(p, "confirm"))
            if action == "land"
            else guards.check_rtl(state, confirm=_flag(p, "confirm"))
        )
        pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
        if pre is not None:
            return pre
        outcome = await self._blocking(verb)
        if not outcome.accepted:
            return self._command_result(action, outcome)
        waited = await self._maybe_wait(p, lambda: self._adapter.get_state().armed is False)
        if waited is False:
            return self._wait_timeout(action, outcome, p, "vehicle did not disarm")
        return self._command_result(action, outcome, waited=waited)

    # -- helpers -----------------------------------------------------------

    def _not_connected(self) -> DaemonResponse:
        return DaemonResponse.failure(
            ExitCode.VEHICLE_NOT_CONNECTED,
            "vehicle not connected (no recent heartbeat)",
            {"connection_string": self._connection_string},
        )

    def _pre_execute(self, decision: GuardDecision, *, dry_run: bool) -> DaemonResponse | None:
        """Return a terminal response for dry-run/reject/idempotent, else None."""

        checks = [c.model_dump() for c in decision.checks]
        if dry_run:
            if not decision.allowed:
                return DaemonResponse.failure(
                    decision.exit_code,
                    decision.message or "would be rejected",
                    {
                        "dry_run": True,
                        "reason": decision.reason,
                        "hint": decision.hint,
                        "checks": checks,
                    },
                )
            return DaemonResponse.success(
                {
                    "dry_run": True,
                    "action": decision.action,
                    "would_execute": not decision.already_satisfied,
                    "already_satisfied": decision.already_satisfied,
                    "note": decision.note,
                    "checks": checks,
                }
            )
        if not decision.allowed:
            return DaemonResponse.failure(
                decision.exit_code,
                decision.message or "rejected by safety guard",
                {"reason": decision.reason, "hint": decision.hint, "checks": checks},
            )
        if decision.already_satisfied:
            return DaemonResponse.success(
                {
                    "action": decision.action,
                    "already_satisfied": True,
                    "note": decision.note,
                    "executed": False,
                }
            )
        return None

    async def _blocking(self, fn: Callable[..., CommandOutcome], *args: Any) -> CommandOutcome:
        loop = asyncio.get_running_loop()
        try:
            return await loop.run_in_executor(None, fn, *args)
        except AdapterError as exc:
            return CommandOutcome(accepted=False, result_name=f"ADAPTER_ERROR: {exc}")

    def _command_result(
        self,
        action: str,
        outcome: CommandOutcome,
        *,
        note: str | None = None,
        waited: bool | None = None,
    ) -> DaemonResponse:
        if not outcome.accepted:
            return DaemonResponse.failure(
                ExitCode.NACK_TIMEOUT,
                f"{action} not accepted by vehicle: {outcome.result_name}",
                {"outcome": outcome.model_dump()},
            )
        result: dict[str, Any] = {"action": action, "executed": True, "outcome": outcome.model_dump()}
        if note is not None:
            result["note"] = note
        if waited is not None:
            result["waited"] = waited
        return DaemonResponse.success(result)

    async def _maybe_wait(
        self, params: dict[str, Any], predicate: Callable[[], bool]
    ) -> bool | None:
        """Return None if not waiting, else True/False for reached/timed-out."""

        if not _flag(params, "wait"):
            return None
        timeout = _timeout(params)
        loop = asyncio.get_running_loop()
        deadline = loop.time() + timeout
        while loop.time() < deadline:
            if predicate():
                return True
            await asyncio.sleep(0.25)
        return predicate()

    def _wait_timeout(
        self, action: str, outcome: CommandOutcome, params: dict[str, Any], detail: str
    ) -> DaemonResponse:
        return DaemonResponse.failure(
            ExitCode.NACK_TIMEOUT,
            f"{action} accepted but did not complete within {_timeout(params):.0f}s: {detail}",
            {"outcome": outcome.model_dump(), "waited": False},
        )

    def _reached_altitude(self, target: float) -> bool:
        rel = self._adapter.get_telemetry().position.relative_alt_m
        return rel is not None and rel >= target

    # -- teardown ----------------------------------------------------------

    def _install_signal_handlers(self) -> None:
        loop = asyncio.get_running_loop()
        for sig in (signal.SIGTERM, signal.SIGINT):
            with contextlib.suppress(NotImplementedError):
                loop.add_signal_handler(sig, self.request_stop)

    async def _shutdown(self) -> None:
        if self._server is not None:
            self._server.close()
            with contextlib.suppress(Exception):
                await self._server.wait_closed()
            self._server = None
        self._adapter.disconnect()
        with contextlib.suppress(FileNotFoundError):
            socket_path().unlink()


def _flag(params: dict[str, Any], key: str) -> bool:
    return bool(params.get(key, False))


def _timeout(params: dict[str, Any]) -> float:
    value = params.get("timeout")
    try:
        return float(value) if value is not None else _DEFAULT_WAIT_TIMEOUT
    except (TypeError, ValueError):
        return _DEFAULT_WAIT_TIMEOUT

